args.content:
// yamlResolver.mjs — YAML 1.1 scalar tag resolution and scalar construction,
// replicating PyYAML's SafeLoader/SafeConstructor behavior.
//
// All matching is done with hand-written character scanners; no regular
// expressions and no JSON helpers are used anywhere in this module.
//
// Value shapes returned (the inter-module contract):
//   null      -> null
//   bool      -> true / false
//   int       -> number (safe range) or BigInt
//   float     -> number (Infinity / -Infinity / NaN included)
//   str       -> string
//   timestamp -> { __yamlTag: 'tag:yaml.org,2002:timestamp', __yamlText: <canonical> }
//   binary    -> { __yamlTag: 'tag:yaml.org,2002:binary',    __yamlText: <base64> }

export const YAML_TAG_PREFIX = 'tag:yaml.org,2002:';

// A scalar equal to `<<` resolves to the merge tag; the parser treats this
// specially in key position and rejects it in value position.
export const MERGE_TAG = 'tag:yaml.org,2002:merge';

const BOOL_WORDS = {
  yes: true, Yes: true, YES: true,
  no: false, No: false, NO: false,
  true: true, True: true, TRUE: true,
  false: false, False: false, FALSE: false,
  on: true, On: true, ON: true,
  off: false, Off: false, OFF: false,
};

function isDigit(c) {
  return c >= '0' && c <= '9';
}

function isHexDigit(c) {
  return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F');
}

// ---------------------------------------------------------------------------
// Implicit resolvers (pattern matchers mirroring PyYAML's resolver regexes)
// ---------------------------------------------------------------------------

// ^(?:~|null|Null|NULL|)$
export function matchNull(s) {
  return s === '' || s === '~' || s === 'null' || s === 'Null' || s === 'NULL';
}

// ^(?:yes|Yes|YES|no|No|NO|true|True|TRUE|false|False|FALSE|on|On|ON|off|Off|OFF)$
export function matchBool(s) {
  return Object.prototype.hasOwnProperty.call(BOOL_WORDS, s);
}

// ^(?:[-+]?0b[0-1_]+|[-+]?0[0-7_]+|[-+]?(?:0|[1-9][0-9_]*)|[-+]?0x[0-9a-fA-F_]+|[-+]?[1-9][0-9_]*(?::[0-5]?[0-9])+)$
export function matchInt(s) {
  let i = 0;
  if (s[i] === '-' || s[i] === '+') i++;
  const rest = s.slice(i);
  if (rest.length === 0) return false;

  // binary: 0b[0-1_]+
  if (rest[0] === '0' && rest[1] === 'b') {
    if (rest.length === 2) return false;
    for (let j = 2; j < rest.length; j++) {
      const c = rest[j];
      if (c !== '0' && c !== '1' && c !== '_') return false;
    }
    return true;
  }
  // hex: 0x[0-9a-fA-F_]+
  if (rest[0] === '0' && rest[1] === 'x') {
    if (rest.length === 2) return false;
    for (let j = 2; j < rest.length; j++) {
      const c = rest[j];
      if (!isHexDigit(c) && c !== '_') return false;
    }
    return true;
  }
  // sexagesimal: [1-9][0-9_]*(?::[0-5]?[0-9])+
  if (rest[0] >= '1' && rest[0] <= '9') {
    let j = 0;
    while (j < rest.length && (isDigit(rest[j]) || rest[j] === '_')) j++;
    if (j < rest.length && rest[j] === ':') {
      // one or more :dd groups (1-2 digits, first 0-5)
      let k = j;
      let groups = 0;
      while (k < rest.length && rest[k] === ':') {
        k++;
        let d = 0;
        while (k < rest.length && isDigit(rest[k]) && d < 2) { k++; d++; }
        if (d === 0) return false;
        // group value must match [0-5]?[0-9]: single digit, or two digits with first 0-5
        const grp = rest.slice(k - d, k);
        if (d === 2 && !(grp[0] >= '0' && grp[0] <= '5')) return false;
        groups++;
      }
      return k === rest.length && groups > 0;
    }
    // decimal: [1-9][0-9_]*
    return j === rest.length;
  }
  // octal: 0[0-7_]+  (also plain "0" is decimal)
  if (rest[0] === '0') {
    if (rest.length === 1) return true; // "0"
    for (let j = 1; j < rest.length; j++) {
      const c = rest[j];
      if (!((c >= '0' && c <= '7') || c === '_')) return false;
    }
    return true;
  }
  return false;
}

// ^(?:[-+]?(?:[0-9][0-9_]*)\.[0-9_]*(?:[eE][-+][0-9]+)?|\.[0-9_]+(?:[eE][-+][0-9]+)?
//   |[-+]?[0-9][0-9_]*(?::[0-5]?[0-9])+\.[0-9_]*|[-+]?\.(?:inf|Inf|INF)|\.(?:nan|NaN|NAN))$
export function matchFloat(s) {
  // .inf / .nan forms
  let body = s;
  let i = 0;
  if (body[i] === '-' || body[i] === '+') i++;
  const afterSign = body.slice(i);
  if (afterSign === '.inf' || afterSign === '.Inf' || afterSign === '.INF') return true;
  if (s[0] !== '-' && s[0] !== '+') {
    if (s === '.nan' || s === '.NaN' || s === '.NAN') return true;
  }

  // sexagesimal float: [-+]?[0-9][0-9_]*(:[0-5]?[0-9])+\.[0-9_]*
  {
    let j = i;
    if (j < s.length && isDigit(s[j])) {
      let k = j;
      while (k < s.length && (isDigit(s[k]) || s[k] === '_')) k++;
      // try sexagesimal: requires at least one :group then a dot
      let m = k;
      let groups = 0;
      let ok = true;
      while (m < s.length && s[m] === ':') {
        m++;
        let d = 0;
        while (m < s.length && isDigit(s[m]) && d < 2) { m++; d++; }
        if (d === 0) { ok = false; break; }
        const grp = s.slice(m - d, m);
        if (d === 2 && !(grp[0] >= '0' && grp[0] <= '5')) { ok = false; break; }
        groups++;
      }
      if (ok && groups > 0 && m < s.length && s[m] === '.') {
        m++;
        while (m < s.length && (isDigit(s[m]) || s[m] === '_')) m++;
        if (m === s.length) return true;
      }
    }
  }

  // decimal float: [-+]?([0-9][0-9_]*\.[0-9_]*|\.[0-9_]+)([eE][-+][0-9]+)?
  {
    let j = i;
    let saw = false;
    if (j < s.length && isDigit(s[j])) {
      while (j < s.length && (isDigit(s[j]) || s[j] === '_')) j++;
      if (j < s.length && s[j] === '.') {
        j++;
        while (j < s.length && (isDigit(s[j]) || s[j] === '_')) j++;
        saw = true;
      }
    } else if (j < s.length && s[j] === '.') {
      j++;
      const start = j;
      while (j < s.length && (isDigit(s[j]) || s[j] === '_')) j++;
      if (j > start) saw = true; // \.[0-9_]+ requires at least one char
    }
    if (!saw) return false;
    // optional exponent — sign is REQUIRED (matches the executable: 1.5e3 is a str)
    if (j < s.length && (s[j] === 'e' || s[j] === 'E')) {
      j++;
      if (j < s.length && (s[j] === '-' || s[j] === '+')) j++;
      else return false;
      const start = j;
      while (j < s.length && isDigit(s[j])) j++;
      if (j === start) return false;
    }
    return j === s.length;
  }
}

// Timestamp matcher; on success returns the captured components, else null.
// ^(?:[0-9]{4}-[0-9]{2}-[0-9]{2}
//   |[0-9]{4}-[0-9]{1,2}-[0-9]{1,2}(?:[Tt]|[ \t]+)[0-9]{1,2}:[0-9]{2}:[0-9]{2}
//     (?:\.[0-9]*)?(?:[ \t]*(?:Z|[-+][0-9]{1,2}(?::[0-9]{2})?))?)$
export function matchTimestamp(s) {
  const n = s.length;
  // date-only form needs exactly 10 chars
  if (n === 10 &&
      isDigit(s[0]) && isDigit(s[1]) && isDigit(s[2]) && isDigit(s[3]) &&
      s[4] === '-' && isDigit(s[5]) && isDigit(s[6]) &&
      s[7] === '-' && isDigit(s[8]) && isDigit(s[9])) {
    return {
      year: +s.slice(0, 4), month: +s.slice(5, 7), day: +s.slice(8, 10),
      dateOnly: true,
    };
  }
  // datetime form
  let i = 0;
  if (n < 15) return null;
  for (let k = 0; k < 4; k++) { if (!isDigit(s[i + k])) return null; }
  const year = +s.slice(0, 4);
  i = 4;
  if (s[i] !== '-') return null;
  i++;
  let start = i;
  while (i < n && isDigit(s[i]) && i - start < 2) i++;
  if (i === start) return null;
  const month = +s.slice(start, i);
  if (s[i] !== '-') return null;
  i++;
  start = i;
  while (i < n && isDigit(s[i]) && i - start < 2) i++;
  if (i === start) return null;
  const day = +s.slice(start, i);
  // separator: T, t, or one/more spaces/tabs
  if (s[i] === 'T' || s[i] === 't') {
    i++;
  } else if (s[i] === ' ' || s[i] === '\t') {
    while (i < n && (s[i] === ' ' || s[i] === '\t')) i++;
  } else {
    return null;
  }
  // hour: 1-2 digits
  start = i;
  while (i < n && isDigit(s[i]) && i - start < 2) i++;
  if (i === start) return null;
  const hour = +s.slice(start, i);
  if (s[i] !== ':') return null;
  i++;
  // minute: exactly 2 digits
  if (!(i + 1 < n && isDigit(s[i]) && isDigit(s[i + 1]))) return null;
  const minute = +(s[i] + s[i + 1]);
  i += 2;
  if (s[i] !== ':') return null;
  i++;
  // second: exactly 2 digits
  if (!(i + 1 < n && isDigit(s[i]) && isDigit(s[i + 1]))) return null;
  const second = +(s[i] + s[i + 1]);
  i += 2;
  // optional fraction: .[0-9]*
  let fraction = '';
  if (s[i] === '.') {
    i++;
    start = i;
    while (i < n && isDigit(s[i])) i++;
    fraction = s.slice(start, i);
  }
  // optional timezone: [ \t]*(Z|[-+][0-9]{1,2}(:[0-9]{2})?)
  let tz = null;
  while (i < n && (s[i] === ' ' || s[i] === '\t')) i++;
  if (i < n) {
    if (s[i] === 'Z') {
      tz = { sign: '+', hour: 0, minute: 0 };
      i++;
    } else if (s[i] === '-' || s[i] === '+') {
      const sign = s[i];
      i++;
      start = i;
      while (i < n && isDigit(s[i]) && i - start < 2) i++;
      if (i === start) return null;
      const tzh = +s.slice(start, i);
      let tzm = 0;
      if (s[i] === ':') {
        i++;
        if (!(i + 1 < n && isDigit(s[i]) && isDigit(s[i + 1]))) return null;
        tzm = +(s[i] + s[i + 1]);
        i += 2;
      }
      tz = { sign, hour: tzh, minute: tzm };
    } else {
      return null;
    }
  }
  if (i !== n) return null;
  return { year, month, day, hour, minute, second, fraction, tz, dateOnly: false };
}

// ---------------------------------------------------------------------------
// Constructors (mirror PyYAML SafeConstructor)
// ---------------------------------------------------------------------------

function stripUnderscores(s) {
  let out = '';
  for (let i = 0; i < s.length; i++) if (s[i] !== '_') out += s[i];
  return out;
}

function toSafeNumberOrBigInt(big) {
  const max = BigInt(Number.MAX_SAFE_INTEGER);
  const min = BigInt(Number.MIN_SAFE_INTEGER);
  if (big <= max && big >= min) return Number(big);
  return big;
}

export function constructInt(raw) {
  let value = stripUnderscores(raw);
  let sign = 1n;
  if (value[0] === '-') { sign = -1n; value = value.slice(1); }
  else if (value[0] === '+') { value = value.slice(1); }
  if (value.length === 0) throw new Error(`invalid int: '${raw}'`);
  let big;
  if (value.length > 2 && value[0] === '0' && value[1] === 'b') {
    const digits = value.slice(2);
    if (digits.length === 0) throw new Error(`invalid int: '${raw}'`);
    big = 0n;
    for (const c of digits) {
      if (c !== '0' && c !== '1') throw new Error(`invalid int: '${raw}'`);
      big = big * 2n + BigInt(c.charCodeAt(0) - 48);
    }
  } else if (value.length > 2 && value[0] === '0' && value[1] === 'x') {
    const digits = value.slice(2);
    if (digits.length === 0) throw new Error(`invalid int: '${raw}'`);
    big = 0n;
    for (const c of digits) {
      if (!isHexDigit(c)) throw new Error(`invalid int: '${raw}'`);
      big = big * 16n + BigInt(parseInt(c, 16));
    }
  } else if (value.indexOf(':') !== -1) {
    // sexagesimal
    big = 0n;
    let parts = value.split(':');
    for (const part of parts) {
      if (part.length === 0) throw new Error(`invalid int: '${raw}'`);
      let d = 0n;
      for (const c of part) {
        if (!isDigit(c)) throw new Error(`invalid int: '${raw}'`);
        d = d * 10n + BigInt(c.charCodeAt(0) - 48);
      }
      big = big * 60n + d;
    }
  } else if (value[0] === '0' && value.length > 1) {
    // octal (leading zero)
    const digits = value.slice(1);
    big = 0n;
    for (const c of digits) {
      if (!(c >= '0' && c <= '7')) throw new Error(`invalid int: '${raw}'`);
      big = big * 8n + BigInt(c.charCodeAt(0) - 48);
    }
  } else {
    big = 0n;
    for (const c of value) {
      if (!isDigit(c)) throw new Error(`invalid int: '${raw}'`);
      big = big * 10n + BigInt(c.charCodeAt(0) - 48);
    }
  }
  return toSafeNumberOrBigInt(sign * big);
}

export function constructFloat(raw) {
  let value = stripUnderscores(raw).toLowerCase();
  let sign = 1;
  if (value[0] === '-') { sign = -1; value = value.slice(1); }
  else if (value[0] === '+') { value = value.slice(1); }
  if (value === '.inf') return sign * Infinity;
  if (value === '.nan') return NaN;
  if (value.indexOf(':') !== -1) {
    // sexagesimal float
    const parts = value.split(':');
    let f = 0;
    for (let k = 0; k < parts.length; k++) {
      const part = parts[k];
      if (part.length === 0) throw new Error(`invalid float: '${raw}'`);
      let d = Number(part); // parts validated by matcher or digits+dot
      if (Number.isNaN(d)) throw new Error(`invalid float: '${raw}'`);
      f = f * 60 + d;
    }
    return sign * f;
  }
  const f = Number(value);
  if (value.length === 0 || Number.isNaN(f)) throw new Error(`invalid float: '${raw}'`);
  return sign * f;
}

export function constructBool(raw) {
  if (Object.prototype.hasOwnProperty.call(BOOL_WORDS, raw)) return BOOL_WORDS[raw];
  throw new Error(`invalid bool: '${raw}'`);
}

export function constructNull(_raw) {
  return null;
}

function isLeapYear(y) {
  return (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
}

function daysInMonth(y, m) {
  switch (m) {
    case 1: case 3: case 5: case 7: case 8: case 10: case 12: return 31;
    case 4: case 6: case 9: case 11: return 30;
    case 2: return isLeapYear(y) ? 29 : 28;
    default: return 0;
  }
}

function pad2(n) {
  return n < 10 ? '0' + n : '' + n;
}

function pad4(n) {
  let s = '' + n;
  while (s.length < 4) s = '0' + s;
  return s;
}

// Construct a timestamp: validates ranges like Python's datetime and returns
// the contract object carrying the canonical text PyYAML would re-dump
// (datetime.isoformat(' ') / date.isoformat()).
export function constructTimestamp(raw) {
  const m = matchTimestamp(raw);
  if (!m) throw new Error(`invalid timestamp: '${raw}'`);
  if (m.month < 1 || m.month > 12) throw new Error('month must be in 1..12');
  if (m.day < 1 || m.day > daysInMonth(m.year, m.month)) {
    throw new Error('day is out of range for month');
  }
  const datePart = pad4(m.year) + '-' + pad2(m.month) + '-' + pad2(m.day);
  if (m.dateOnly) {
    return { __yamlTag: YAML_TAG_PREFIX + 'timestamp', __yamlText: datePart };
  }
  if (m.hour > 23) throw new Error('hour must be in 0..23');
  if (m.minute > 59) throw new Error('minute must be in 0..59');
  if (m.second > 59) throw new Error('second must be in 0..59');
  let text = datePart + ' ' + pad2(m.hour) + ':' + pad2(m.minute) + ':' + pad2(m.second);
  // fraction: truncate to 6 digits, right-pad with zeros; omit when zero
  if (m.fraction && m.fraction.length > 0) {
    let frac = m.fraction.slice(0, 6);
    while (frac.length < 6) frac += '0';
    if (frac !== '000000') text += '.' + frac;
  }
  if (m.tz) {
    // Python timezone offsets must be strictly less than 24 hours
    if (m.tz.hour > 23 || (m.tz.hour === 24) || m.tz.minute > 59) {
      throw new Error('tz offset out of range');
    }
    text += m.tz.sign + pad2(m.tz.hour) + ':' + pad2(m.tz.minute);
  }
  return { __yamlTag: YAML_TAG_PREFIX + 'timestamp', __yamlText: text };
}

export function constructBinary(raw) {
  // PyYAML decodes base64 (ignoring non-alphabet characters) and re-encodes
  // it; for well-formed input that is the input with whitespace removed.
  let out = '';
  for (let i = 0; i < raw.length; i++) {
    const c = raw[i];
    if (c === ' ' || c === '\t' || c === '\n') continue;
    out += c;
  }
  return { __yamlTag: YAML_TAG_PREFIX + 'binary', __yamlText: out };
}

export function constructStr(raw) {
  return raw;
}

// ---------------------------------------------------------------------------
// Top-level resolution entry points
// ---------------------------------------------------------------------------

// Implicit resolution for plain (unquoted, untagged) scalars.
export function resolvePlainScalar(text) {
  if (matchNull(text)) return null;
  if (matchBool(text)) return BOOL_WORDS[text];
  if (matchInt(text)) return constructInt(text);
  if (matchFloat(text)) return constructFloat(text);
  const ts = matchTimestamp(text);
  if (ts) return constructTimestamp(text);
  return text;
}

// What tag a plain scalar would implicitly resolve to (used by the parser to
// detect merge keys). Returns the full tag URI.
export function plainScalarTag(text) {
  if (matchNull(text)) return YAML_TAG_PREFIX + 'null';
  if (matchBool(text)) return YAML_TAG_PREFIX + 'bool';
  if (matchInt(text)) return YAML_TAG_PREFIX + 'int';
  if (matchFloat(text)) return YAML_TAG_PREFIX + 'float';
  if (text === '<<') return MERGE_TAG;
  if (matchTimestamp(text)) return YAML_TAG_PREFIX + 'timestamp';
  return YAML_TAG_PREFIX + 'str';
}

// Construct a scalar under an explicit full tag (e.g. from `!!int`).
// `kind` is 'scalar' here; collection tags are handled by the parser.
export function constructTaggedScalar(fullTag, text) {
  switch (fullTag) {
    case YAML_TAG_PREFIX + 'str': return text;
    case YAML_TAG_PREFIX + 'int': return constructInt(text);
    case YAML_TAG_PREFIX + 'float': return constructFloat(text);
    case YAML_TAG_PREFIX + 'bool': return constructBool(text);
    case YAML_TAG_PREFIX + 'null': return null;
    case YAML_TAG_PREFIX + 'timestamp': return constructTimestamp(text);
    case YAML_TAG_PREFIX + 'binary': return constructBinary(text);
    case YAML_TAG_PREFIX + 'value': return text;
    default:
      throw new Error(`could not determine a constructor for the tag ${fullTag}`);
  }
}

// Resolve a `!!suffix` / verbatim tag to a full tag URI, or null if unknown.
const KNOWN_SUFFIXES = new Set([
  'str', 'int', 'float', 'bool', 'null', 'binary', 'timestamp',
  'seq', 'map', 'set', 'omap', 'pairs', 'merge', 'value',
]);

export function resolveTagSuffix(suffix) {
  if (KNOWN_SUFFIXES.has(suffix)) return YAML_TAG_PREFIX + suffix;
  return null;
}

