// Scalar analysis and rendering helpers for the PyYAML-compatible emitter.
// Everything here is hand-written character scanning (no RegExp, no JSON).

export const YAML_TAG_PREFIX = 'tag:yaml.org,2002:';

const BREAK_NEL = ''; // NEL
const BREAK_LS = ' '; // LINE SEPARATOR
const BREAK_PS = ' '; // PARAGRAPH SEPARATOR

export function isBreakChar(ch) {
  return ch === '\n' || ch === BREAK_NEL || ch === BREAK_LS || ch === BREAK_PS;
}

// Mirror of PyYAML's Emitter.analyze_scalar (only the flags the emitter needs).
export function analyzeScalar(scalar) {
  if (scalar === '') {
    return { empty: true, multiline: false, allowBlock: false };
  }
  const cps = Array.from(scalar); // iterate by code point, like Python str
  let lineBreaks = false;
  let specialCharacters = false;
  let trailingSpace = false;
  let spaceBreak = false;
  let prev = null;
  for (let i = 0; i < cps.length; i++) {
    const ch = cps[i];
    const cp = ch.codePointAt(0);
    if (isBreakChar(ch)) lineBreaks = true;
    if (!(ch === '\n' || (cp >= 0x20 && cp <= 0x7E))) {
      // With allow_unicode=False every non-ASCII character is "special",
      // and every non-printable ASCII character is special as well.
      specialCharacters = true;
    }
    if (ch === ' ') {
      if (i === cps.length - 1) trailingSpace = true;
    }
    if (isBreakChar(ch) && prev === ' ') spaceBreak = true;
    prev = ch;
  }
  let allowBlock = true;
  if (trailingSpace) allowBlock = false;
  if (spaceBreak || specialCharacters) allowBlock = false;
  return { empty: false, multiline: lineBreaks, allowBlock };
}

// Mirror of PyYAML's Emitter.determine_block_hints (best_indent == 2).
export function determineBlockHints(text) {
  let hints = '';
  if (text !== '') {
    const cps = Array.from(text);
    const first = cps[0];
    const last = cps[cps.length - 1];
    if (first === ' ' || isBreakChar(first)) hints += '2';
    if (!isBreakChar(last)) {
      hints += '-';
    } else if (cps.length === 1 || isBreakChar(cps[cps.length - 2])) {
      hints += '+';
    }
  }
  return hints;
}

// Python repr() of a float, including PyYAML's represent_float fixups
// ('1e+16' -> '1.0e+16'). Returns the canonical scalar text for a float.
export function floatScalarText(x) {
  if (Number.isNaN(x)) return '.nan';
  if (x === Infinity) return '.inf';
  if (x === -Infinity) return '-.inf';
  let neg = false;
  if (x < 0 || Object.is(x, -0)) neg = true;
  const s = Math.abs(x).toExponential(); // shortest round-trip, "d[.ddd]e±X"
  let mant = s;
  let expStr = '';
  for (let i = 0; i < s.length; i++) {
    if (s[i] === 'e') {
      mant = s.slice(0, i);
      expStr = s.slice(i + 1);
      break;
    }
  }
  const e = parseInt(expStr, 10);
  // digits: mantissa without the dot (first digit, then the rest)
  let digits = mant[0];
  for (let i = 1; i < mant.length; i++) {
    if (mant[i] !== '.') digits += mant[i];
  }
  let body;
  if (e >= -4 && e < 16) {
    // fixed notation
    if (e >= digits.length - 1) {
      body = digits;
      for (let i = digits.length - 1; i < e; i++) body += '0';
      body += '.0';
    } else if (e >= 0) {
      body = digits.slice(0, e + 1) + '.' + digits.slice(e + 1);
    } else {
      body = '0.';
      for (let i = 0; i < -e - 1; i++) body += '0';
      body += digits;
    }
  } else {
    // scientific notation, exponent at least two digits with sign
    body = digits[0];
    if (digits.length > 1) body += '.' + digits.slice(1);
    let expAbs = Math.abs(e).toString();
    if (expAbs.length < 2) expAbs = '0' + expAbs;
    body += 'e' + (e < 0 ? '-' : '+') + expAbs;
    // PyYAML represent_float: if '.' not in value and 'e' in value -> '.0e'
    if (digits.length === 1) {
      // body is like "1e+16" -> "1.0e+16"
      body = digits[0] + '.0' + body.slice(1);
    }
  }
  return neg ? '-' + body : body;
}

function isDigit(ch) {
  return ch >= '0' && ch <= '9';
}

function removeUnderscores(s) {
  let out = '';
  for (let i = 0; i < s.length; i++) {
    if (s[i] !== '_') out += s[i];
  }
  return out;
}

function allCharsIn(s, allowed) {
  if (s.length === 0) return false;
  for (let i = 0; i < s.length; i++) {
    let ok = false;
    for (let j = 0; j < allowed.length; j++) {
      if (s[i] === allowed[j]) { ok = true; break; }
    }
    if (!ok) return false;
  }
  return true;
}

function parseBigIntBase(digits, base) {
  let v = 0n;
  const b = BigInt(base);
  for (let i = 0; i < digits.length; i++) {
    const c = digits[i];
    let d;
    if (c >= '0' && c <= '9') d = c.charCodeAt(0) - 48;
    else if (c >= 'a' && c <= 'f') d = c.charCodeAt(0) - 87;
    else if (c >= 'A' && c <= 'F') d = c.charCodeAt(0) - 55;
    else return null;
    if (d >= base) return null;
    v = v * b + BigInt(d);
  }
  return v;
}

// YAML 1.1 int resolver (PyYAML):
//   [-+]?0b[0-1_]+ | [-+]?0[0-7_]+ | [-+]?(0|[1-9][0-9_]*)
//   | [-+]?0x[0-9a-fA-F_]+ | [-+]?[1-9][0-9_]*(:[0-5]?[0-9])+
// Returns a BigInt or null.
export function matchYamlInt(key) {
  let s = key;
  let sign = 1n;
  if (s.length > 0 && s[0] === '+') {
    s = s.slice(1);
  } else if (s.length > 0 && s[0] === '-') {
    sign = -1n;
    s = s.slice(1);
  }
  if (s === '') return null;
  if (s.length > 2 && s[0] === '0' && s[1] === 'b') {
    const rest = s.slice(2);
    if (!allCharsIn(rest, '01_')) return null;
    const v = parseBigIntBase(removeUnderscores(rest), 2);
    return v === null ? null : sign * v;
  }
  if (s.length > 2 && s[0] === '0' && (s[1] === 'x' || s[1] === 'X')) {
    // Note: PyYAML only allows lowercase 0x, handled by caller ordering;
    // keep strict: only 'x'
    if (s[1] !== 'x') return null;
    const rest = s.slice(2);
    if (!allCharsIn(rest, '0123456789abcdefABCDEF_')) return null;
    const v = parseBigIntBase(removeUnderscores(rest), 16);
    return v === null ? null : sign * v;
  }
  // sexagesimal: [1-9][0-9_]*(:[0-5]?[0-9])+
  let colon = -1;
  for (let i = 0; i < s.length; i++) {
    if (s[i] === ':') { colon = i; break; }
  }
  if (colon > 0) {
    const parts = s.split(':');
    if (parts.length >= 2) {
      const head = parts[0];
      let headOk = head.length >= 1 && head[0] >= '1' && head[0] <= '9';
      if (headOk) {
        for (let i = 1; i < head.length; i++) {
          if (!isDigit(head[i]) && head[i] !== '_') { headOk = false; break; }
        }
      }
      if (headOk) {
        let v = parseBigIntBase(removeUnderscores(head), 10);
        let ok = v !== null;
        for (let p = 1; p < parts.length && ok; p++) {
          const part = parts[p];
          if (part.length < 1 || part.length > 2) { ok = false; break; }
          if (!isDigit(part[0]) || part[0] > '5') { ok = false; break; }
          if (part.length === 2 && !isDigit(part[1])) { ok = false; break; }
          v = v * 60n + BigInt(removeUnderscores(part));
        }
        if (ok) return sign * v;
      }
      return null;
    }
  }
  // octal: 0[0-7_]+
  if (s.length > 1 && s[0] === '0') {
    const rest = s.slice(1);
    if (!allCharsIn(rest, '01234567_')) return null;
    const v = parseBigIntBase(removeUnderscores(rest), 8);
    return v === null ? null : sign * v;
  }
  // decimal: 0 | [1-9][0-9_]*
  if (s === '0') return 0n;
  if (s[0] >= '1' && s[0] <= '9') {
    for (let i = 1; i < s.length; i++) {
      if (!isDigit(s[i]) && s[i] !== '_') return null;
    }
    const v = parseBigIntBase(removeUnderscores(s), 10);
    return v === null ? null : sign * v;
  }
  return null;
}

// YAML 1.1 float resolver (PyYAML):
//   [-+]?([0-9][0-9_]*)\.[0-9_]*([eE][-+][0-9]+)?
//   | \.[0-9][0-9_]*([eE][-+][0-9]+)?
//   | [-+]?[0-9][0-9_]*(:[0-5]?[0-9])+\.[0-9_]*
//   | [-+]?\.(inf|Inf|INF) | \.(nan|NaN|NAN)
// Returns a JS number or null.
export function matchYamlFloat(key) {
  let s = key;
  let sign = 1;
  let hadSign = false;
  if (s.length > 0 && s[0] === '+') { hadSign = true; s = s.slice(1); }
  else if (s.length > 0 && s[0] === '-') { hadSign = true; sign = -1; s = s.slice(1); }
  if (s === '.inf' || s === '.Inf' || s === '.INF') return sign * Infinity;
  if (!hadSign && (s === '.nan' || s === '.NaN' || s === '.NAN')) return NaN;
  if (s === '') return null;
  // sexagesimal float: [0-9][0-9_]*(:[0-5]?[0-9])+\.[0-9_]*
  let hasColon = false;
  for (let i = 0; i < s.length; i++) {
    if (s[i] === ':') { hasColon = true; break; }
  }
  if (hasColon) {
    // split off the fractional part at the last '.'
    let dot = -1;
    for (let i = s.length - 1; i >= 0; i--) {
      if (s[i] === '.') { dot = i; break; }
    }
    if (dot < 0) return null;
    const intPart = s.slice(0, dot);
    const fracPart = s.slice(dot + 1);
    if (!allCharsIn(fracPart.length ? fracPart : '_', '0123456789_') && fracPart !== '') {
      // [0-9_]* allows empty; validate chars only
    }
    for (let i = 0; i < fracPart.length; i++) {
      if (!isDigit(fracPart[i]) && fracPart[i] !== '_') return null;
    }
    const parts = intPart.split(':');
    if (parts.length < 2) return null;
    const head = parts[0];
    if (!(head.length >= 1 && isDigit(head[0]))) return null;
    for (let i = 1; i < head.length; i++) {
      if (!isDigit(head[i]) && head[i] !== '_') return null;
    }
    let v = parseFloat(removeUnderscores(head));
    for (let p = 1; p < parts.length; p++) {
      const part = parts[p];
      if (part.length < 1 || part.length > 2) return null;
      if (!isDigit(part[0]) || part[0] > '5') return null;
      if (part.length === 2 && !isDigit(part[1])) return null;
      v = v * 60 + parseInt(part, 10);
    }
    const frac = parseFloat('0.' + (removeUnderscores(fracPart) || '0'));
    return sign * (v + frac);
  }
  // plain decimal float: [0-9][0-9_]*\.[0-9_]* | \.[0-9][0-9_]*  (+optional exp)
  // find exponent part
  let mant = s;
  let exp = '';
  for (let i = 0; i < s.length; i++) {
    if (s[i] === 'e' || s[i] === 'E') {
      mant = s.slice(0, i);
      exp = s.slice(i + 1);
      break;
    }
  }
  if (exp !== '') {
    // exponent must be [-+][0-9]+
    if (exp[0] !== '+' && exp[0] !== '-') return null;
    if (exp.length < 2) return null;
    for (let i = 1; i < exp.length; i++) {
      if (!isDigit(exp[i])) return null;
    }
  } else if (mant !== s) {
    return null; // "1.5e" style: 'e' with empty exponent
  }
  // mantissa: either digits '.' digits*  or  '.' digit digits*
  let dot = -1;
  for (let i = 0; i < mant.length; i++) {
    if (mant[i] === '.') { dot = i; break; }
  }
  if (dot < 0) return null;
  const intPart = mant.slice(0, dot);
  const fracPart = mant.slice(dot + 1);
  if (intPart === '') {
    // \.[0-9][0-9_]*
    if (fracPart.length === 0 || !isDigit(fracPart[0])) return null;
    for (let i = 1; i < fracPart.length; i++) {
      if (!isDigit(fracPart[i]) && fracPart[i] !== '_') return null;
    }
  } else {
    // [0-9][0-9_]*\.[0-9_]*
    if (!isDigit(intPart[0])) return null;
    for (let i = 1; i < intPart.length; i++) {
      if (!isDigit(intPart[i]) && intPart[i] !== '_') return null;
    }
    for (let i = 0; i < fracPart.length; i++) {
      if (!isDigit(fracPart[i]) && fracPart[i] !== '_') return null;
    }
  }
  const cleaned = removeUnderscores(intPart) + '.' + removeUnderscores(fracPart) +
    (exp !== '' ? 'e' + exp : '');
  return sign * Number(cleaned);
}

// YAML 1.1 timestamp resolver (PyYAML). Returns 'date', 'dt', or null.
export function matchYamlTimestamp(key) {
  const n = key.length;
  // date: [0-9]{4}-[0-9]{2}-[0-9]{2}
  if (n === 10 && isDigit(key[0]) && isDigit(key[1]) && isDigit(key[2]) && isDigit(key[3]) &&
      key[4] === '-' && isDigit(key[5]) && isDigit(key[6]) &&
      key[7] === '-' && isDigit(key[8]) && isDigit(key[9])) {
    return 'date';
  }
  // [0-9]{4}-[0-9][0-9]?-[0-9][0-9]?([Tt]|[ \t]+)[0-9][0-9]?:[0-9]{2}:[0-9]{2}(\.[0-9]*)?
  //   ([ \t]*(Z|[-+][0-9][0-9]?(:[0-9]{2})?))?
  let i = 0;
  if (n < 15) return null;
  for (let k = 0; k < 4; k++) { if (!isDigit(key[i])) return null; i++; }
  if (key[i] !== '-') return null; i++;
  if (!isDigit(key[i])) return null; i++;
  if (isDigit(key[i])) i++;
  if (key[i] !== '-') return null; i++;
  if (!isDigit(key[i])) return null; i++;
  if (isDigit(key[i])) i++;
  // separator
  if (key[i] === 'T' || key[i] === 't') {
    i++;
  } else if (key[i] === ' ' || key[i] === '\t') {
    while (key[i] === ' ' || key[i] === '\t') i++;
  } else {
    return null;
  }
  if (!isDigit(key[i])) return null; i++;
  if (isDigit(key[i])) i++;
  if (key[i] !== ':') return null; i++;
  if (!isDigit(key[i])) return null; i++;
  if (!isDigit(key[i])) return null; i++;
  if (key[i] !== ':') return null; i++;
  if (!isDigit(key[i])) return null; i++;
  if (!isDigit(key[i])) return null; i++;
  // fraction
  if (key[i] === '.') {
    i++;
    while (i < n && isDigit(key[i])) i++;
  }
  // timezone
  if (i < n) {
    while (key[i] === ' ' || key[i] === '\t') i++;
    if (i >= n) return 'dt';
    if (key[i] === 'Z') {
      i++;
      if (i !== n) return null;
      return 'dt';
    }
    if (key[i] === '+' || key[i] === '-') {
      i++;
      if (!isDigit(key[i])) return null; i++;
      if (isDigit(key[i])) i++;
      if (i < n && key[i] === ':') {
        i++;
        if (!isDigit(key[i])) return null; i++;
        if (!isDigit(key[i])) return null; i++;
      }
      if (i !== n) return null;
      return 'dt';
    }
    return null;
  }
  return 'dt';
}

// Resolve a (coerced, string) mapping key the way PyYAML's implicit resolver
// would, and produce the canonical scalar text PyYAML would re-dump.
// Result: { tag, text, cls, numBig, numNum, tsKind }
export function resolveKey(key) {
  if (key === '' || key === '~' || key === 'null' || key === 'Null' || key === 'NULL') {
    return { tag: YAML_TAG_PREFIX + 'null', text: 'null', cls: 'null', numBig: null, numNum: null, tsKind: null };
  }
  switch (key) {
    case 'yes': case 'Yes': case 'YES': case 'true': case 'True': case 'TRUE':
    case 'on': case 'On': case 'ON':
      return { tag: YAML_TAG_PREFIX + 'bool', text: 'true', cls: 'num', numBig: null, numNum: 1, tsKind: null };
    case 'no': case 'No': case 'NO': case 'false': case 'False': case 'FALSE':
    case 'off': case 'Off': case 'OFF':
      return { tag: YAML_TAG_PREFIX + 'bool', text: 'false', cls: 'num', numBig: null, numNum: 0, tsKind: null };
    default:
      break;
  }
  const iv = matchYamlInt(key);
