// PyYAML-compatible emitter for yaml.dump(value, default_style='>').
// Faithful port of PyYAML's emitter state machine (column/whitespace/indention
// tracking, folded and double-quoted writers, anchor/alias handling, key
// sorting) restricted to the JS-value contract of the parser module:
//   null / boolean / number / BigInt / string / Array / plain Object /
//   { __yamlTag, __yamlText } wrappers.
// No RegExp, no JSON, no external dependencies.

import {
  YAML_TAG_PREFIX,
  isBreakChar,
  analyzeScalar,
  determineBlockHints,
  floatScalarText,
  resolveKey,
  codePointCompare,
} from './yamlEmitterAnalysis.mjs';

const TAG_STR = YAML_TAG_PREFIX + 'str';

// PyYAML ESCAPE_REPLACEMENTS for the double-quoted writer.
const ESCAPE_REPLACEMENTS = new Map([
  ['\0', '0'],
  ['\x07', 'a'],
  ['\x08', 'b'],
  ['\x09', 't'],
  ['\x0A', 'n'],
  ['\x0B', 'v'],
  ['\x0C', 'f'],
  ['\x0D', 'r'],
  ['\x1B', 'e'],
  ['"', '"'],
  ['\\', '\\'],
  ['\x85', 'N'],
  ['\xA0', '_'],
  ['\u2028', 'L'],
  ['\u2029', 'P'],
]);

function hexUpper(cp, width) {
  let s = cp.toString(16).toUpperCase();
  while (s.length < width) s = '0' + s;
  return s;
}

function isWrapper(v) {
  return (
    v !== null &&
    typeof v === 'object' &&
    !Array.isArray(v) &&
    typeof v.__yamlTag === 'string' &&
    typeof v.__yamlText === 'string'
  );
}

// Collections and tag wrappers can be anchored/aliased (like PyYAML, which
// only ignores aliasing for None and str/bytes/bool/int/float scalars).
function isAliasable(v) {
  return v !== null && typeof v === 'object';
}

class Emitter {
  constructor() {
    this.out = [];
    this.column = 0;
    this.whitespace = true;
    this.indention = true;
    this.openEnded = false;
    this.indent = null;
    this.indents = [];
    this.bestIndent = 2;
    this.bestWidth = 80;
    this.anchorId = 0;
    this.anchors = new Map(); // object -> anchor name ('id001') or null
    this.serialized = new Set(); // objects already fully emitted
  }

  // ---- low-level writers (mirrors of PyYAML Emitter methods) ----

  writeRaw(data) {
    this.column += data.length;
    this.out.push(data);
  }

  writeIndicator(indicator, needWhitespace, whitespace = false, indention = false) {
    let data;
    if (this.whitespace || !needWhitespace) {
      data = indicator;
    } else {
      data = ' ' + indicator;
    }
    this.whitespace = whitespace;
    this.indention = indention;
    this.column += data.length;
    this.openEnded = false;
    this.out.push(data);
  }

  writeIndent() {
    const indent = this.indent === null ? 0 : this.indent;
    if (!this.indention || this.column > indent ||
        (this.column === indent && !this.whitespace)) {
      this.writeLineBreak();
    }
    if (this.column < indent) {
      this.whitespace = true;
      let data = '';
      for (let i = this.column; i < indent; i++) data += ' ';
      this.column = indent;
      this.out.push(data);
    }
  }

  writeLineBreak() {
    this.whitespace = true;
    this.indention = true;
    this.column = 0;
    this.out.push('\n');
  }

  increaseIndent(flow = false, indentless = false) {
    this.indents.push(this.indent);
    if (this.indent === null) {
      this.indent = flow ? this.bestIndent : 0;
    } else if (!indentless) {
      this.indent += this.bestIndent;
    }
  }

  decreaseIndent() {
    this.indent = this.indents.pop();
  }

  // ---- scalar writers ----

  // Mirror of PyYAML Emitter.write_double_quoted (allow_unicode=False).
  writeDoubleQuoted(text, split) {
    this.writeIndicator('"', true);
    const cps = Array.from(text);
    const n = cps.length;
    let start = 0;
    let end = 0;
    while (end <= n) {
      const ch = end < n ? cps[end] : null;
      const cp = ch === null ? -1 : ch.codePointAt(0);
      if (ch === null || ch === '"' || ch === '\\' ||
          ch === '\x85' || ch === '\u2028' || ch === '\u2029' || cp === 0xFEFF ||
          !(cp >= 0x20 && cp <= 0x7E)) {
        if (start < end) {
          this.writeRaw(cps.slice(start, end).join(''));
          start = end;
        }
        if (ch !== null) {
          let data;
          if (ESCAPE_REPLACEMENTS.has(ch)) {
            data = '\\' + ESCAPE_REPLACEMENTS.get(ch);
          } else if (cp <= 0xFF) {
            data = '\\x' + hexUpper(cp, 2);
          } else if (cp <= 0xFFFF) {
            data = '\\u' + hexUpper(cp, 4);
          } else {
            data = '\\U' + hexUpper(cp, 8);
          }
          this.writeRaw(data);
          start = end + 1;
        }
      }
      if (0 < end && end < n - 1 && (ch === ' ' || start >= end) &&
          this.column + (end - start) > this.bestWidth && split) {
        const data = cps.slice(start, end).join('') + '\\';
        if (start < end) start = end;
        this.writeRaw(data);
        this.writeIndent();
        this.whitespace = false;
        this.indention = false;
        if (cps[start] === ' ') {
          this.writeRaw('\\');
        }
      }
      end++;
    }
    this.writeIndicator('"', false);
  }

  // Mirror of PyYAML Emitter.write_folded.
  writeFolded(text) {
    const hints = determineBlockHints(text);
    this.writeIndicator('>' + hints, true);
    if (hints.length > 0 && hints[hints.length - 1] === '+') {
      this.openEnded = true;
    }
    this.writeLineBreak();
    const cps = Array.from(text);
    const n = cps.length;
    let leadingSpace = true;
    let spaces = false;
    let breaks = true;
    let start = 0;
    let end = 0;
    while (end <= n) {
      const ch = end < n ? cps[end] : null;
      if (breaks) {
        if (ch === null || !isBreakChar(ch)) {
          if (!leadingSpace && ch !== null && ch !== ' ' && cps[start] === '\n') {
            this.writeLineBreak();
          }
          leadingSpace = ch === ' ';
          for (let i = start; i < end; i++) {
            this.writeLineBreak();
          }
          if (ch !== null) {
            this.writeIndent();
          }
          start = end;
        }
      } else if (spaces) {
        if (ch !== ' ') {
          if (start + 1 === end && this.column > this.bestWidth &&
              start !== 0 && end !== n) {
            this.writeIndent();
          } else {
            this.writeRaw(cps.slice(start, end).join(''));
          }
          start = end;
        }
      } else {
        if (ch === null || ch === ' ' || isBreakChar(ch)) {
          this.writeRaw(cps.slice(start, end).join(''));
          if (ch === null) {
            this.writeLineBreak();
          }
          start = end;
        }
      }
      if (ch !== null) {
        breaks = isBreakChar(ch);
        spaces = ch === ' ';
      }
      end++;
    }
  }

  // ---- tags ----

  prepareTag(tag) {
    if (tag.startsWith(YAML_TAG_PREFIX)) {
      return '!!' + tag.slice(YAML_TAG_PREFIX.length);
    }
    return '!<' + tag + '>';
  }

  // ---- nodes ----

  // tag/text for a scalar JS value
  scalarInfo(v) {
    if (v === null) return { tag: YAML_TAG_PREFIX + 'null', text: 'null' };
    if (typeof v === 'boolean') return { tag: YAML_TAG_PREFIX + 'bool', text: v ? 'true' : 'false' };
    if (typeof v === 'bigint') return { tag: YAML_TAG_PREFIX + 'int', text: v.toString() };
    if (typeof v === 'number') {
      if (Number.isSafeInteger(v)) return { tag: YAML_TAG_PREFIX + 'int', text: v.toString() };
      return { tag: YAML_TAG_PREFIX + 'float', text: floatScalarText(v) };
    }
    if (typeof v === 'string') return { tag: TAG_STR, text: v };
    // wrapper object
    return { tag: v.__yamlTag, text: v.__yamlText };
  }

  // Emit a scalar. ctx.simpleKey selects the mapping-key behavior.
  emitScalar(tag, text, simpleKey) {
    const analysis = analyzeScalar(text);
    let style;
    if (simpleKey) {
      style = '"';
    } else if (analysis.allowBlock) {
      style = '>';
    } else {
      style = '"';
    }
    // Non-plain styles suppress the tag only when it is the default str tag
    // (PyYAML: implicit[1]).
    if (tag !== TAG_STR) {
      this.writeIndicator(this.prepareTag(tag), true);
    }
    if (style === '>') {
      const saved = this.indent;
      this.indent = (saved === null ? 0 : saved) + this.bestIndent;
      this.writeFolded(text);
      this.indent = saved;
    } else {
      this.writeDoubleQuoted(text, !simpleKey);
    }
  }

  emitNode(v, ctx) {
    // aliases / anchors
    if (isAliasable(v)) {
      if (this.serialized.has(v)) {
        this.writeIndicator('*' + this.anchors.get(v), true);
        return;
      }
      this.serialized.add(v);
      const anchor = this.anchors.get(v);
      if (anchor !== null && anchor !== undefined) {
        this.writeIndicator('&' + anchor, true);
      }
    }
    if (Array.isArray(v)) {
      this.emitSequence(v, ctx);
    } else if (v !== null && typeof v === 'object' && !isWrapper(v)) {
      this.emitMapping(v, ctx);
    } else {
      const info = this.scalarInfo(v);
      this.emitScalar(info.tag, info.text, false);
    }
  }

  emitSequence(arr, ctx) {
    if (arr.length === 0) {
      this.writeIndicator('[', true);
      this.writeIndicator(']', true);
      return;
    }
    const indentless = !!(ctx && ctx.mapping) && !this.indention;
    this.increaseIndent(false, indentless);
    for (const item of arr) {
      this.writeIndent();
      this.writeIndicator('-', true, false, true);
      this.emitNode(item, { sequence: true });
    }
    this.decreaseIndent();
  }

  emitMapping(obj, ctx) {
    const entries = this.getEntries(obj);
    if (entries.length === 0) {
      this.writeIndicator('{', true);
      this.writeIndicator('}', true);
      return;
    }
    this.increaseIndent(false, false);
    for (const e of entries) {
      this.writeIndent();
      if (e.simple) {
        this.emitScalar(e.tag, e.text, true);
        this.writeIndicator(':', false);
        this.emitNode(e.value, { mapping: true });
      } else {
        this.writeIndicator('?', true, false, true);
        this.emitScalar(e.tag, e.text, false);
        this.writeIndent();
        this.writeIndicator(':', true, false, true);
        this.emitNode(e.value, { mapping: true });
      }
    }
    this.decreaseIndent();
  }

  // Sorted mapping entries with resolved/canonicalized keys.
  // Mirrors PyYAML represent_mapping's sorted() (sort_keys=True default):
  // keys comparable -> sorted; mixed types -> TypeError -> insertion order.
  getEntries(obj) {
    const keys = Object.keys(obj);
    const entries = keys.map((k) => {
      const r = resolveKey(k);
      const analysis = analyzeScalar(r.text);
      const preparedTagLen = this.prepareTag(r.tag).length;
      const simple = !analysis.empty && !analysis.multiline &&
        (Array.from(r.text).length + preparedTagLen) < 128;
      return {
        jkey: k,
        value: obj[k],
        tag: r.tag,
        text: r.text,
        cls: r.cls,
        numBig: r.numBig,
        numNum: r.numNum,
        tsKind: r.tsKind,
        simple,
      };
    });
    if (entries.length > 1) {
      const cls0 = entries[0].cls;
      let uniform = entries.every((e) => e.cls === cls0);
      if (uniform && cls0 === 'ts') {
        // Python date vs datetime comparison raises TypeError
        const k0 = entries[0].tsKind;
        uniform = entries.every((e) => e.tsKind === k0);
      }
      if (uniform && cls0 === 'str') {
        entries.sort((a, b) => codePointCompare(a.text, b.text));
      } else if (uniform && cls0 === 'num') {
        entries.sort((a, b) => {
          if (a.numBig !== null && b.numBig !== null) {
            return a.numBig < b.numBig ? -1 : a.numBig > b.numBig ? 1 : 0;
          }
          const x = a.numNum;
          const y = b.numNum;
          if (Number.isNaN(x) || Number.isNaN(y)) return 0;
          return x < y ? -1 : x > y ? 1 : 0;
        });
      } else if (uniform && cls0 === 'ts') {
        entries.sort((a, b) => codePointCompare(a.text, b.text));
      }
      // cls 'null' or non-uniform: keep insertion order (Python TypeError fallback)
    }
    return entries;
  }

  // Pre-pass that assigns anchors to multiply-referenced nodes, in document
  // (emission) order, mirroring PyYAML's Serializer.anchor_node.
  anchorNode(v) {
    if (!isAliasable(v)) return;
    if (this.anchors.has(v)) {
      if (this.anchors.get(v) === null) {
        this.anchorId += 1;
        let num = this.anchorId.toString();
        while (num.length < 3) num = '0' + num;
        this.anchors.set(v, 'id' + num);
      }
      return;
    }
    this.anchors.set(v, null);
    if (Array.isArray(v)) {
      for (const item of v) this.anchorNode(item);
    } else if (!isWrapper(v)) {
      for (const e of this.getEntries(v)) {
        this.anchorNode(e.value);
      }
    }
  }
}

// yaml.dump(value, default_style='>') equivalent.
export function dumpFolded(value) {
  const em = new Emitter();
  em.anchorNode(value);
  em.emitNode(value, { root: true });
  // document end
  em.writeIndent();
  if (em.openEnded) {
    em.writeIndicator('...', true);
    em.writeLineBreak();
  }
  return em.out.join('');
}

