  prepareTag(tag) {
    if (tag.startsWith(YAML_TAG_PREFIX)) {
      return '!!' + tag.slice(YAML_TAG_PREFIX.length);
    }
    return '!<' + tag + '>';
  }

  // ---- nodes ----

  // tag/text for a scalar JS value
  scalarInfo(v) {
    if (v === null) return { tag: YAML_TAG_PREFIX + 'null', text: 'null' };
    if (typeof v === 'boolean') return { tag: YAML_TAG_PREFIX + 'bool', text: v ? 'true' : 'false' };
    if (typeof v === 'bigint') return { tag: YAML_TAG_PREFIX + 'int', text: v.toString() };
    if (typeof v === 'number') {
      if (Number.isSafeInteger(v)) return { tag: YAML_TAG_PREFIX + 'int', text: v.toString() };
      return { tag: YAML_TAG_PREFIX + 'float', text: floatScalarText(v) };
    }
    if (typeof v === 'string') return { tag: TAG_STR, text: v };
    // wrapper object
    return { tag: v.__yamlTag, text: v.__yamlText };
  }

  // Emit a scalar. ctx.simpleKey selects the mapping-key behavior.
  emitScalar(tag, text, simpleKey) {
    const analysis = analyzeScalar(text);
    let style;
    if (simpleKey) {
      style = '"';
    } else if (analysis.allowBlock) {
      style = '>';
    } else {
      style = '"';
    }
    // Non-plain styles suppress the tag only when it is the default str tag
    // (PyYAML: implicit[1]).
    if (tag !== TAG_STR) {
      this.writeIndicator(this.prepareTag(tag), true);
    }
    if (style === '>') {
      const saved = this.indent;
      this.indent = (saved === null ? 0 : saved) + this.bestIndent;
      this.writeFolded(text);
      this.indent = saved;
    } else {
      this.writeDoubleQuoted(text, !simpleKey);
    }
  }

  emitNode(v, ctx) {
    // aliases / anchors
    if (isAliasable(v)) {
      if (this.serialized.has(v)) {
        this.writeIndicator('*' + this.anchors.get(v), true);
        return;
      }
      this.serialized.add(v);
      const anchor = this.anchors.get(v);
      if (anchor !== null && anchor !== undefined) {
        this.writeIndicator('&' + anchor, true);
      }
    }
    if (Array.isArray(v)) {
      this.emitSequence(v, ctx);
    } else if (v !== null && typeof v === 'object' && !isWrapper(v)) {
      this.emitMapping(v, ctx);
    } else {
      const info = this.scalarInfo(v);
      this.emitScalar(info.tag, info.text, false);
    }
  }

  emitSequence(arr, ctx) {
    if (arr.length === 0) {
      this.writeIndicator('[', true);
      this.writeIndicator(']', true);
      return;
    }
    const indentless = !!(ctx && ctx.mapping) && !this.indention;
    this.increaseIndent(false, indentless);
    for (const item of arr) {
      this.writeIndent();
      this.writeIndicator('-', true, false, true);
      this.emitNode(item, { sequence: true });
    }
    this.decreaseIndent();
  }

  emitMapping(obj, ctx) {
    const entries = this.getEntries(obj);
    if (entries.length === 0) {
      this.writeIndicator('{', true);
      this.writeIndicator('}', true);
      return;
    }
    this.increaseIndent(false, false);
    for (const e of entries) {
      this.writeIndent();
      if (e.simple) {
        this.emitScalar(e.tag, e.text, true);
        this.writeIndicator(':', false);
        this.emitNode(e.value, { mapping: true });
      } else {
        this.writeIndicator('?', true, false, true);
        this.emitScalar(e.tag, e.text, false);
        this.writeIndent();
        this.writeIndicator(':', true, false, true);
        this.emitNode(e.value, { mapping: true });
      }
    }
    this.decreaseIndent();
  }

  // Sorted mapping entries with resolved/canonicalized keys.
  // Mirrors PyYAML represent_mapping's sorted() (sort_keys=True default):
  // keys comparable -> sorted; mixed types -> TypeError -> insertion order.
  getEntries(obj) {
    const keys = Object.keys(obj);
    const entries = keys.map((k) => {
      const r = resolveKey(k);
      const analysis = analyzeScalar(r.text);
      const preparedTagLen = this.prepareTag(r.tag).length;
      const simple = !analysis.empty && !analysis.multiline &&
        (Array.from(r.text).length + preparedTagLen) < 128;
      return {
        jkey: k,
        value: obj[k],
        tag: r.tag,
        text: r.text,
        cls: r.cls,
        numBig: r.numBig,
        numNum: r.numNum,
        tsKind: r.tsKind,
        simple,
      };
    });
    if (entries.length > 1) {
      const cls0 = entries[0].cls;
      let uniform = entries.every((e) => e.cls === cls0);
      if (uniform && cls0 === 'ts') {
        // Python date vs datetime comparison raises TypeError
        const k0 = entries[0].tsKind;
        uniform = entries.every((e) => e.tsKind === k0);
      }
      if (uniform && cls0 === 'str') {
        entries.sort((a, b) => codePointCompare(a.text, b.text));
      } else if (uniform && cls0 === 'num') {
        entries.sort((a, b) => {
          if (a.numBig !== null && b.numBig !== null) {
            return a.numBig < b.numBig ? -1 : a.numBig > b.numBig ? 1 : 0;
          }
          const x = a.numNum;
          const y = b.numNum;
          if (Number.isNaN(x) || Number.isNaN(y)) return 0;
          return x < y ? -1 : x > y ? 1 : 0;
        });
      } else if (uniform && cls0 === 'ts') {
        entries.sort((a, b) => codePointCompare(a.text, b.text));
      }
      // cls 'null' or non-uniform: keep insertion order (Python TypeError fallback)
    }
    return entries;
  }

  // Pre-pass that assigns anchors to multiply-referenced nodes, in document
  // (emission) order, mirroring PyYAML's Serializer.anchor_node.
  anchorNode(v) {
    if (!isAliasable(v)) return;
    if (this.anchors.has(v)) {
      if (this.anchors.get(v) === null) {
        this.anchorId += 1;
        let num = this.anchorId.toString();
        while (num.length < 3) num = '0' + num;
        this.anchors.set(v, 'id' + num);
      }
      return;
    }
    this.anchors.set(v, null);
    if (Array.isArray(v)) {
      for (const item of v) this.anchorNode(item);
    } else if (!isWrapper(v)) {
      for (const e of this.getEntries(v)) {
        this.anchorNode(e.value);
      }
    }
  }
}

// yaml.dump(value, default_style='>') equivalent.
export function dumpFolded(value) {
  const em = new Emitter();
  em.anchorNode(value);
  em.emitNode(value, { root: true });
  // document end
  em.writeIndent();
  if (em.openEnded) {
    em.writeIndicator('...', true);
    em.writeLineBreak();
  }
  return em.out.join('');
}
